def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        base = 8.0 if hp > 3 else 18.0
        return float(max(0.0, min(budget, base)))

    pressure_bids = []
    desperate_count = 0
    rich_live = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            pressure_bids.append(float(prev['bid']))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 200:
            rich_live += 1

    highest_prev = max(pressure_bids) if pressure_bids else 0.0
    avg_prev = sum(pressure_bids) / len(pressure_bids) if pressure_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 2 or no_water_days >= 2
    semi_urgent = hp <= 4 or no_water_days >= 1

    if urgent:
        bid = max(62.0, highest_prev + 3.0, 70.0 + 20.0 * scarcity)
        return float(max(0.0, min(budget, bid)))

    if semi_urgent:
        bid = max(38.0, avg_prev + 2.0, 42.0 + 12.0 * scarcity)
        if supply <= 17:
            bid = max(bid, highest_prev + 2.5)
        return float(max(0.0, min(budget, bid)))

    if supply >= 22:
        bid = 12.0 + 4.0 * scarcity
        if highest_prev > 120:
            bid = min(bid, 16.0)
        return float(max(0.0, min(budget, bid)))

    if supply >= 19:
        bid = 18.0 + 10.0 * scarcity
        if desperate_count >= 2:
            bid += 6.0
        if highest_prev > 90:
            bid = min(bid, 28.0)
        return float(max(0.0, min(budget, bid)))

    bid = 26.0 + 18.0 * scarcity + 3.0 * desperate_count
    if rich_live >= 1 and highest_prev >= 100:
        bid = min(bid, 36.0)
    else:
        bid = max(bid, min(highest_prev + 1.5, 55.0))

    if day >= 8 and hp > 5:
        bid *= 0.9

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 1))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday's immediate behavior
    prev_bids = []
    prev_by_agent = {}
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
                prev_bids.append(b_val)
                prev_by_agent[o.get('agent_id', '')] = b_val
            except Exception:
                pass

    # Estimate how aggressive the field was
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    else:
        highest_prev = 0.0
        second_prev = 0.0

    # Determine today's urgency from supply and my hp
    # Higher supply reduces urgency; low supply increases urgency.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # If I'm in danger, bid to secure at least one allocation.
    danger = 0
    if my_hp <= 2.0:
        danger = 2
    elif my_hp <= 4.0:
        danger = 1
    if my_no_water_days >= 2:
        danger += 1

    # Target bid logic:
    # - If Cindy-like high bid existed yesterday (highest_prev high), try to slightly undercut/beat with a small premium.
    # - Otherwise bid moderately.
    base = DAILY_SALARY * (0.35 + 0.25 * supply_norm)  # 0.35..0.60 of salary

    # When opponent pressure was high, match it with a controlled increment.
    if highest_prev >= DAILY_SALARY * 0.85:
        # Bid just above the second-highest to win without paying the absolute highest.
        target = max(base, second_prev + 2.0)
        # If I'm safe, don't overpay.
        if danger == 0:
            target = min(target, highest_prev - 1.0)
        else:
            target = min(highest_prev + 1.0, target + 3.0)
    elif highest_prev >= DAILY_SALARY * 0.55:
        # Moderate pressure: bid around base but slightly above highest_prev if needed.
        target = max(base, highest_prev * 0.95)
        if danger >= 1:
            target = max(target, highest_prev + 1.5)
    else:
        # Low pressure: conserve.
        target = base
        if danger >= 2:
            target = max(target, DAILY_SALARY * 0.75)

    # Convert to feasible bid given budget
    # Also keep within a reasonable range to avoid bankruptcy.
    floor_bid = 1.0
    cap = my_budget
    if cap <= 0.0:
        return 0.0

    # If supply is extremely low, increase urgency.
    if supply < float(WATER_REQ) + 1.0:
        target = max(target, DAILY_SALARY * 0.7)

    bid = max(floor_bid, min(cap, target))
    return float(bid)
